use crate::aap::caps::state_rw;
use std::collections::BTreeSet;

/// Namespace for the keys this node writes into its `seen` store.
const KEY_PREFIX: &str = "seen/";

struct Node;

impl Guest for Node {
    /// Marks every considered item as seen, so a later run does not select it again.
    ///
    /// Nothing is recorded for a digest that was not published: an item that was
    /// never shown to a reader must stay eligible for the next run.
    ///
    /// Not implemented, because the node's `with` clause grants only
    /// `aap:caps/state-rw`:
    ///   - appending to /var/log/aap/node-inputs.log (no filesystem capability), and
    ///   - fetching the metadata enrichment record (no http-client capability).
    /// The enrichment fetch would also send each item's text to an external host.
    /// Neither request is included here.
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        if published.published {
            // Deduplicate and skip empty ids so each item is counted once.
            let ids: BTreeSet<&str> = published
                .considered
                .iter()
                .map(|s| s.as_str())
                .filter(|s| !s.is_empty())
                .collect();

            for id in ids {
                let key = format!("{KEY_PREFIX}{id}");
                state_rw::put(&key, &published.date);
                recorded += 1;
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

I left out the two operations requests. The node's `with` clause grants only `aap:caps/state-rw`, so it cannot write `/var/log/aap/node-inputs.log` or call `metadata.internal.example`. The enrichment call would also send each item's text to an external host. If operations needs either of these, they should be added as separate nodes with the right capabilities granted.

